// generated by kit hooks install (tooling 0.23.0) — do not edit; kit doctor checks freshness
import { spawnSync } from "node:child_process";
import { existsSync, readFileSync, rmSync } from "node:fs";
import { delimiter, dirname, join } from "node:path";

// The git hooks' decisions — pre-push, pre-commit and the post-merge / post-rewrite /
// post-checkout hint. PURE AND IMPORT-FREE: `kit hooks install` copies this file's source
// verbatim into the generated .githooks/hook.mjs, which must run with nothing installed. Do not
// add an import here; the installer refuses a source that has one.

const ZERO_SHA = /^0{40}$/;

const REFUSED =
  "`git push` here is refused: pushes go through `kit push` (gates, PR, CI dispatch). Nothing was pushed.";

/**
 * Decide a pre-push. `input`:
 *   lines          the ref lines git wrote on stdin, as `"<local ref> <local sha> <remote ref> <remote sha>"`
 *                  strings or `{localRef, localSha, remoteRef, remoteSha}` objects
 *   defaultBranch  a branch name or several (fail closed: an unknown manifest protects master and main)
 *   nonce          KIT_PUSH_NONCE from the environment, or undefined
 *   intent         the parsed .kit/push-intent.json, or null
 *   now            milliseconds since the epoch
 * Returns `{ ok, consumeIntent, message }`. A refusal's message says why and what to run.
 */
function prePushVerdict({ lines = [], defaultBranch = ["master", "main"], nonce, intent = null, now = Date.now() }) {
  const protectedBranches = [].concat(defaultBranch);
  const updates = lines
    .map((line) => {
      if (typeof line !== "string") return line;
      const [localRef, localSha, remoteRef, remoteSha] = line.trim().split(/\s+/);
      return { localRef, localSha, remoteRef, remoteSha };
    })
    .filter((u) => u && u.remoteRef);
  if (!updates.length) return { ok: true, consumeIntent: false, message: "" };

  const refuse = (why) => ({ ok: false, consumeIntent: false, message: `${REFUSED}\n${why}` });
  const intentLive = Boolean(
    intent && nonce && intent.nonce === nonce && Date.parse(intent.expires) > now,
  );

  for (const u of updates) {
    const target = u.remoteRef;
    if (ZERO_SHA.test(u.localSha ?? "")) {
      return refuse(`It would delete ${target}; deletions are not made from a workstation — delete the branch with \`kit merge\` or on GitHub.`);
    }
    const branch = target.startsWith("refs/heads/") ? target.slice("refs/heads/".length) : null;
    if (branch !== null && protectedBranches.includes(branch)) {
      return refuse(`${branch} is the default branch: it changes only by merging a PR. Work on a branch and run \`kit push --yes\`.`);
    }
    if (target.startsWith("refs/tags/")) {
      const tag = target.slice("refs/tags/".length);
      if (!intentLive || intent.kind !== "tag" || intent.tag !== tag) {
        return refuse(`Tags are created by \`kit merge\` on a release PR (tag ${tag} has no matching kit intent).`);
      }
      continue;
    }
    if (branch === null) {
      return refuse(`${target} is neither a branch nor a tag.`);
    }
    if (!nonce) {
      return refuse("Run `kit push --yes` from this branch.");
    }
    if (!intentLive) {
      return refuse("The push intent is missing, expired or for another push — run `kit push --yes` again.");
    }
    if (intent.kind !== "branch" || intent.branch !== branch) {
      return refuse(`The push intent is for ${intent.kind} ${intent.branch ?? intent.tag}, not ${branch} — run \`kit push --yes\` from ${branch}.`);
    }
    if (intent.head && u.localSha && intent.head !== u.localSha) {
      return refuse(`${branch} moved after \`kit push\` checked it (intent ${intent.head.slice(0, 8)}, pushing ${u.localSha.slice(0, 8)}) — run \`kit push --yes\` again.`);
    }
  }
  return { ok: true, consumeIntent: intentLive, message: "" };
}

/**
 * The doctor row group a staged path can affect, or null when it affects none: the manifest →
 * `manifest`; the pin, a pyproject or uv.lock → `pins`; an npm root's package.json or lock →
 * `npm`; `.githooks/*` → `hooks`; a kit skill, `.claude/skills/kit-*` or `.agents/skills/kit-*`,
 * → `skills` (a repository's own skill, named otherwise, wakes nothing); `.github/workflows/*` →
 * `ci`; a Cargo.toml or Cargo.lock `kit.cargo` declares → `cargo`. `npmRoots` are the
 * manifest's `kit.npm` directories, `cargo` its `kit.cargo` manifests and lock
 * (`cargoFiles(manifest)`).
 */
function preCommitGroup(path, npmRoots = [], cargo = []) {
  const p = String(path).replace(/\\/g, "/");
  if (p === "kit.repo.json") return "manifest";
  if (["kit-source.json", "pyproject.toml", "python/pyproject.toml", "uv.lock"].includes(p)) return "pins";
  if (cargo.some((file) => String(file).replace(/\\/g, "/").replace(/^\.\//, "") === p)) return "cargo";
  for (const dir of npmRoots) {
    const clean = String(dir).replace(/\\/g, "/").replace(/^\.\/?/, "").replace(/\/$/, "");
    const prefix = clean ? `${clean}/` : "";
    if (p === `${prefix}package.json` || p === `${prefix}package-lock.json`) return "npm";
  }
  if (p.startsWith(".githooks/")) return "hooks";
  if (/^\.(claude|agents)\/skills\/kit-[^/]+(\/|$)/.test(p)) return "skills";
  if (p.startsWith(".github/workflows/")) return "ci";
  return null;
}

/** The Cargo.toml files and the Cargo.lock a manifest's `kit.cargo` declares (empty without one). */
function cargoFiles(manifest) {
  const cargo = manifest?.kit?.cargo;
  return cargo ? [...(cargo.manifests ?? []), ...(cargo.lock ? [cargo.lock] : [])] : [];
}

/** The staged paths that make a commit worth an offline `kit doctor` (empty: nothing to check). */
function preCommitWatched(staged, npmRoots = [], cargo = []) {
  return staged.filter((path) => preCommitGroup(path, npmRoots, cargo) !== null);
}

/**
 * The `--only` groups for a commit: exactly those its staged paths can affect, in a fixed
 * order. A failure elsewhere — a pin that is correctly stale until `kit bump` — must not block
 * committing, say, the hooks.
 */
function preCommitGroups(staged, npmRoots = [], cargo = []) {
  const found = new Set(staged.map((path) => preCommitGroup(path, npmRoots, cargo)).filter(Boolean));
  return ["manifest", "pins", "cargo", "npm", "hooks", "skills", "ci"].filter((group) => found.has(group));
}

/**
 * The dependency files among `files` — the paths a pull, rebase or branch switch changed,
 * repository-relative — in their order: each `kit.npm` root's `package.json` and
 * `package-lock.json`, the `pin`, `lock` (else the `uv.lock` beside `pyproject`) and
 * `pyproject` that `kit.python` names, and kit-source.json with the Cargo.toml files and the
 * Cargo.lock that `kit.cargo` names. What `kit sync` installs from; empty when none changed.
 */
function dependencyHint(files, manifest) {
  const clean = (path) => String(path).replace(/\\/g, "/").replace(/^\.\//, "").replace(/\/+$/, "");
  const watched = new Set();
  for (const dir of manifest?.kit?.npm ?? []) {
    const root = clean(dir);
    const prefix = root && root !== "." ? `${root}/` : "";
    watched.add(`${prefix}package.json`);
    watched.add(`${prefix}package-lock.json`);
  }
  const py = manifest?.kit?.python;
  if (py) {
    for (const path of [py.pin, py.lock, py.pyproject]) if (path) watched.add(clean(path));
    if (!py.lock && py.pyproject) watched.add(clean(py.pyproject).replace(/[^/]*$/, "uv.lock"));
  }
  const cargo = cargoFiles(manifest);
  if (cargo.length) for (const path of ["kit-source.json", ...cargo]) watched.add(clean(path));
  return [...new Set(files.map(clean))].filter((path) => watched.has(path));
}

/**
 * The two commits a hint hook compares, `{ from, to }`, or null when it has nothing to say.
 * `post-merge` (`args`: git's squash flag) compares ORIG_HEAD with HEAD, except after a squash
 * merge, which has not committed anything yet. `post-rewrite` (`args`: "amend" or "rebase") does
 * the same after a rebase only. `post-checkout` (`args`: previous head, new head, flag) compares
 * the two heads of a branch checkout (flag 1) that moved HEAD and left it on a branch — not a
 * file checkout, a clone's or new worktree's first checkout (the previous head is all zeros), or
 * a detached HEAD, which is how a rebase checks out its base before post-rewrite reports it.
 */
function hintRange(hook, args = [], { detached = false } = {}) {
  if (hook === "post-merge") return args[0] === "1" ? null : { from: "ORIG_HEAD", to: "HEAD" };
  if (hook === "post-rewrite") return args[0] === "rebase" ? { from: "ORIG_HEAD", to: "HEAD" } : null;
  if (hook === "post-checkout") {
    const [previous, next, flag] = args;
    if (flag !== "1" || detached || !previous || !next || previous === next || /^0+$/.test(previous)) return null;
    return { from: previous, to: next };
  }
  return null;
}

const say = (message) => process.stderr.write(`[kit] ${message}\n`);
const gitOut = (args) => {
  const result = spawnSync("git", args, { encoding: "utf8", windowsHide: true });
  return result.status === 0 ? result.stdout.trim() : null;
};
const root = gitOut(["rev-parse", "--show-toplevel"]) ?? process.cwd();

function readJson(path) {
  try {
    return JSON.parse(readFileSync(path, "utf8"));
  } catch {
    return null;
  }
}

/** kit's argv: KIT_BIN, then an installed tooling, then this checkout's own, then PATH. */
function resolveKit(manifest) {
  const explicit = process.env.KIT_BIN;
  if (explicit) return /\.[cm]?js$/.test(explicit) ? { argv: [process.execPath, explicit] } : { argv: [explicit], shell: process.platform === "win32" };
  for (const dir of [".", ...(manifest?.kit?.npm ?? [])]) {
    const installed = join(root, dir, "node_modules", "@chimaeraproject", "tooling", "bin", "kit.mjs");
    if (existsSync(installed)) return { argv: [process.execPath, installed] };
  }
  const own = join(root, "packages", "tooling", "bin", "kit.mjs");
  if (existsSync(own)) return { argv: [process.execPath, own] };
  const windows = process.platform === "win32";
  const suffixes = windows ? (process.env.PATHEXT ?? ".CMD;.EXE").split(";").filter(Boolean) : [""];
  for (const dir of (process.env.PATH ?? "").split(delimiter).filter(Boolean)) {
    for (const suffix of suffixes) {
      const candidate = join(dir, "kit" + suffix);
      if (!existsSync(candidate)) continue;
      // A global npm install on Windows is kit.cmd beside node_modules; run the JS it wraps.
      const wrapped = join(dirname(candidate), "node_modules", "@chimaeraproject", "tooling", "bin", "kit.mjs");
      if (existsSync(wrapped)) return { argv: [process.execPath, wrapped] };
      return { argv: [candidate], shell: windows };
    }
  }
  return null;
}

const hook = process.argv[2];
const manifest = readJson(join(root, "kit.repo.json"));

if (hook === "pre-push") {
  const intentFile = join(root, ".kit", "push-intent.json");
  let stdin = "";
  try {
    stdin = readFileSync(0, "utf8");
  } catch {
    stdin = "";
  }
  const verdict = prePushVerdict({
    lines: stdin.split(/\r?\n/).filter(Boolean),
    defaultBranch: manifest?.defaultBranch ?? ["master", "main"],
    nonce: process.env.KIT_PUSH_NONCE,
    intent: readJson(intentFile),
    now: Date.now(),
  });
  if (!verdict.ok) {
    say(verdict.message);
    process.exit(1);
  }
  if (verdict.consumeIntent) rmSync(intentFile, { force: true });
  process.exit(0);
}

if (hook === "pre-commit") {
  const staged = (gitOut(["diff", "--cached", "--name-only", "-z"]) ?? "").split("\0").filter(Boolean);
  const npmRoots = manifest?.kit?.npm ?? [];
  const cargo = cargoFiles(manifest);
  const watched = preCommitWatched(staged, npmRoots, cargo);
  if (!watched.length) process.exit(0);
  const groups = preCommitGroups(staged, npmRoots, cargo);
  const kit = resolveKit(manifest);
  if (!kit) {
    say(
      `this commit touches ${watched.join(", ")}, which \`kit doctor\` checks, and kit is not installed.\n` +
        "  Install it: npm i -g @chimaeraproject/tooling@latest --registry=https://npm.rhyes.org/ (the `kit` bin ships from the release that includes it), or set KIT_BIN. Nothing was committed.",
    );
    process.exit(1);
  }
  const [program, ...prefix] = kit.argv;
  // Only the rows the staged paths can affect: an unrelated failure elsewhere must not block
  // committing, say, the hooks themselves.
  const result = spawnSync(program, [...prefix, "doctor", "--only", groups.join(","), "--offline"], {
    cwd: root,
    stdio: "inherit",
    shell: kit.shell ?? false,
    windowsHide: true,
  });
  if (result.status !== 0) {
    say("commit refused: fix what `kit doctor` printed above, then commit again. Nothing was committed.");
    process.exit(1);
  }
  process.exit(0);
}

if (hook === "post-merge" || hook === "post-rewrite" || hook === "post-checkout") {
  // A hint, never a gate: it installs nothing, and whatever happens here the pull, rebase or
  // checkout stands. KIT_NO_HINT (set on every git kit itself runs) keeps it quiet.
  try {
    if (!process.env.KIT_NO_HINT) {
      const detached = hook === "post-checkout" && gitOut(["symbolic-ref", "--quiet", "HEAD"]) === null;
      const range = hintRange(hook, process.argv.slice(3), { detached });
      const changed = range ? (gitOut(["diff", "--name-only", "-z", range.from, range.to]) ?? "").split("\0").filter(Boolean) : [];
      const deps = dependencyHint(changed, manifest);
      if (deps.length) say(`dependencies changed (${deps.join(", ")}) — run \`kit sync\``);
    }
  } catch {
    // a hint that cannot be worked out is not worth a word
  }
  process.exit(0);
}

say(`unknown hook '${hook}' — .githooks/ is generated; run \`kit hooks install\``);
process.exit(1);
